CREATE TABLE DEPARTMENT(DEPTNO NUMBER, NAME VARCHAR(14) not null, PRIMARY KEY(DEPTNO), UNIQUE(NAME));
CREATE TABLE DLOCATION(DEPTNO NUMBER, LOCATION VARCHAR(15) not null, PRIMARY KEY(DEPTNO,LOCATION), FOREIGN KEY(DEPTNO) REFERENCES DEPARTMENT(DEPTNO));
CREATE TABLE EMPLOYEE(IDNUM NUMBER, FNAME VARCHAR(15) not null, LNAME VARCHAR(20) not null, SEX CHAR(1) not null, ADDRESS VARCHAR(20) not null, SALARY NUMBER(7,2) not null, BONUS NUMBER (6,2), JOB VARCHAR(20) not null, DEPTNO NUMBER not null, PRIMARY KEY(IDNUM), FOREIGN KEY(DEPTNO) REFERENCES DEPARTMENT(DEPTNO));
CREATE TABLE DEPENDENT(IDNUM NUMBER, NAME VARCHAR(15) not null, SEX CHAR(1) not null, BDATE DATE not null, RELATIONSHIP NUMBER(1) not null, PRIMARY KEY(IDNUM,NAME), FOREIGN KEY(IDNUM) REFERENCES EMPLOYEE(IDNUM));
CREATE TABLE PROJECT(PROJNO NUMBER, NAME VARCHAR(20) not null, LOCATION VARCHAR(15) not null, DEPTNO NUMBER not null, PRIMARY KEY(PROJNO), UNIQUE(NAME), FOREIGN KEY(DEPTNO) REFERENCES DEPARTMENT(DEPTNO));
CREATE TABLE WORKSON(IDNUM NUMBER not null, PROJNO NUMBER not null, HOURS NUMBER(4), PRIMARY KEY(IDNUM,PROJNO), FOREIGN KEY(IDNUM) REFERENCES EMPLOYEE(IDNUM), FOREIGN KEY(PROJNO) REFERENCES PROJECT(PROJNO));